function C:StatusSound(type, diff)
  if not coroutine.isyieldable() then spawn(C.StatusSound, self, type, diff) return end
  if type ~= "Follower" and type ~= "Yami" and type ~= "Love" and type ~= "Stress" then
    return
  end
  if type == "Follower" or type == "Love" then
    if diff > 0 then
      AudioManager:PlaySeByType("SE_status_up", false)
    else
      AudioManager:PlaySeByType("SE_status_down", false)
    end
