  elseif diff > 10 then
    AudioManager:PlaySeByType("SE_stress_up_lv2", false)
  elseif diff > 0 then
    AudioManager:PlaySeByType("SE_stress_up_lv1", false)
  else
    AudioManager:PlaySeByType("SE_stress_down", false)
  end
  UniTask.Delay(800, false, "Update", nil, false)
end

